                story: 'Юбилейный турнир в честь императора: девятнадцать мастеров, по две партии с каждым — тридцать шесть партий у каждого. Один из самых длинных турниров в истории. Тарраш и Пильсбери разделили первое место, дополнительный матч Тарраш выиграл 2½:1½.',
